option.value:
@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:ital,wght@0,100..900;1,100..900&family=Open+Sans:ital,wght@0,300..800;1,300..800&display=swap');


/* Animação */
@keyframes colorChange {
    0% {
        color: var(--tertiary-color);
    }
    25% {
        color: var(--main-color);
    }
    50% {
        color: var(--secondary-color);
    }
    75% {
        color: var(--inverse-color);
    }
    100% {
        color: var(--tertiary-color);
    }
}

/* Animação para rolagem contínua */
@keyframes scroll {
    0% {
        transform: translateX(0);
    }
    100% {
        transform: translateX(-100%);
    }
}

/* Animação de flutuar */
@keyframes float {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
    100% {
        transform: translateY(0);
    }
}

/* Mudar bordas de imagem */
@keyframes borderRadiusChange {
    0% {
        border-radius: 42.5% 34% 25.5% 51% / 42.5% 25.5% 51% 34%;
    }
    50% {
        border-radius: 25.5% 42.5% 51% 34% / 34% 42.5% 25.5% 42.5%;
    }
    100% {
        border-radius: 42.5% 34% 25.5% 51% / 42.5% 25.5% 51% 34%;
    }
}

:root {
    --main-color: #374B32;
    --secondary-color: #4CA035;
    --tertiary-color: #3d5e35;
    --inverse-color: orange;
    --text1-color: white;
    --text2-color: #171717;
    --text3-color: #555;
    --background: white;
    /* --background: #2C332B; */
    --header: white;
    --gradient: linear-gradient(90deg, #47753B 0%, #8BC34A 100%);
    --blur: blur(5px);
}

/* Configurações globais */
* {
    font-family: 'Inter Tight', sans-serif;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

a {
    text-decoration: none;
    color: inherit;
}

html {
    scroll-behavior: smooth;
}

html, body {
    overflow-x: hidden !important; 
}

/* Scroll */
body::-webkit-scrollbar {
    width: 12px;
    background: #ffffff00;
}

body::-webkit-scrollbar-thumb {
    border-radius: 5px;
    transition: all 0.3s ease;
    background-color: var(--text3-color);
}

body::-webkit-scrollbar-thumb:hover {
    background: rgba(88, 88, 88, 0.459);
}

body {
    display: flex;
    background-color: var(--background);
    font-size: 16px;
    line-height: 1.5;
    width: 100%;
    height: 100%;
}

/* Header */
header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    background-color: rgba(255, 255, 255, 0.119);
    backdrop-filter: var(--blur);
    -webkit-backdrop-filter: var(--blur);
    width: max-content;
    max-width: 94vw;
    padding: 10px 24px;
    margin: 20px auto;
    border-radius: 20px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
    position: fixed;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1000;
}

header .logo {
    display: flex;
    align-items: center;
}

header .logo img {
    border-radius: 50%;
    height: 50px;
    width: 50px;
    object-fit: cover; 
    transition: transform 0.5s, color 0.5s;
}

header .logo img:hover {
    transform: rotate(360deg);
}

header nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

header nav ul {
    display: flex;
    list-style: none;
    white-space: nowrap;
}

header nav ul li {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 8px;
    font-size: 0.95rem;
    font-weight: 500;
    transition: transform 0.3s, color 0.3s;
}

header .fa-brands {
    font-size: 1.8rem;
    margin-right: 10px;
    transition: transform 0.5s, color 0.5s;
}

header .fa-brands:hover, nav ul li:hover {
    transform: scale(1.1);
    color: var(--main-color);
}

/* Estilo para todas alinhar todas as sections */
section .text-center {
    display: flex;
    width: 50%;
    flex-direction: column;
}

/* Padrão de títulos de seção */
.section-label {
    display: block;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 4px;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--secondary-color);
    margin-bottom: 8px;
}

.section-label-light {
    color: rgba(255, 255, 255, 0.75);
}

.section-title {
    text-align: center;
    font-size: clamp(1.6rem, 4vw, 2.2rem);
    font-weight: 700;
    letter-spacing: -0.5px;
    color: var(--text2-color);
    margin-bottom: 40px;
}

/* "Onda" da tela principal */
.wave {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
}

/* Section principal */
main {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    margin-top: 100px;
}

.hello-container {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: 90vh;
    color: var(--text2-color);
}

.hello-container .text-center {
    width: 100%;
    align-items: center;
    text-align: center;
}

.hello-container #hello-text {
    background-color: var(--tertiary-color);
    font-weight: 300;
    color: var(--text1-color);
    padding: 7px 16px;
    border-radius: 10px;
    margin-right: 10px;
    white-space: nowrap;
}

.hello-container span {
    font-size: 2rem;
    font-weight: 400;
}

.hello-container #greeting-text {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
}

.hello-container #name-text {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    margin-top: 10px;
    transition: margin-top 0.3s;
    animation: float 5s infinite;
}

.hello-container h1#name {
    text-align: center;
    color: var(--text2-color);
    font-size: clamp(3rem, 8vw, 5.5rem);
    font-weight: 800;
    letter-spacing: -2px;
    transition: 0.7s;
    line-height: 1;
    margin-top: 5px;
    cursor: pointer;
    animation: colorChange 10s infinite;
}

.hello-container h1#name:hover {
    transform: scale(1.1);
}

.hello-container #job-text {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin-bottom: 20px;
}

.hello-container #job-text p {
    font-size: 1.5rem;
    font-weight: 300;
    color: var(--text3-color);
    transition: font-size 0.3s;
}

.hello-container #job-text span {
    font-weight: 300;
    font-size: 16px;
    color: var(--text3-color);
}

.hello-container button {
    background-color: var(--tertiary-color);
    color: var(--text1-color);
    padding: 15px;
    border: none;
    border-radius: 30px;
    font-size: 1rem;
    cursor: pointer;
    width: 200px;
    transition: transform 0.5s;
}

.hello-container button:hover {
    background-color: var(--main-color);
    transform: scale(1.04);
}

.hello-container button i,
.projects-container .btn i {
    transition: transform 0.3s;
}

.hello-container button:hover i,
.projects-container .btn:hover i {
    transform: translateX(5px);
}

.hello-container .hello-banner {  /* Mantém o titulo principal (eduardo fabri) alinhado */
    width: 50%;
    margin: 140px auto;
}

/* Section de apresentação */
.presentation-container {
    display: flex;
    width: 100%;
    background: var(--gradient);
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 40px;
    color: var(--text1-color);
}

.presentation-container .text-center {
    display: flex;
    flex-direction: row;
}

.presentation-container img {
    animation: borderRadiusChange 10s infinite;
    height: 320px;
    width: 300px;
    margin-right: 40px;
    border-radius: 50px;
    object-fit: cover;
    transition: 0.3s;
    cursor: pointer;
    box-shadow: 10px 10px 5px rgba(2, 5, 10, 0.1);
}

.presentation-container img:hover {
    transform: scale(1.04);
}

.presentation-container .text-me {
    display: flex;
    margin-top: 20px;
    flex-direction: column;
}

.presentation-container .text-me #about-me {
    font-size: 2rem;
    font-weight: 700;
    transition: font-size 0.3s;
}

.presentation-container .text-me #about-me:hover {
    font-size: 2.5rem;
}

.presentation-container #curriculobutton {
    background-color: var(--text2-color);
    color: #fff;
    padding: 10px;
    border: none;
    border-radius: 30px;
    font-size: 1.3rem;
    cursor: pointer;
    width: 200px;
    margin-top: 90px;
    transition: background-color 0.5s;
    border: 1px solid transparent;
    transition: transform 0.5s;
}

.presentation-container #curriculobutton:hover {
    background-color: var(--main-color);
    transform: scale(1.04);
}

/* Section Skills */
.skills-container {
    text-align: center;
    font-family: Arial, sans-serif;
    margin: 50px;
}

.skills-container .skills-title {
    margin-bottom: 50px;
}

.skills-container .carousel {
    position: relative;
    overflow: hidden;
    width: 100%;
    max-width: 800px;
    margin: 0 auto;

    /* Máscara para criar efeito de opacidade nas bordas */
    mask-image: linear-gradient(to right, transparent, black 15%, black 85%, transparent);
    -webkit-mask-image: linear-gradient(to right, transparent, black 15%, black 85%, transparent);
}

.skills-container .carousel-track {
    display: flex;
    animation: scroll 11s linear infinite; 
}

.skills-container .carousel-item {
    min-width: 200px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    color: #aaa;
    transition: color 0.3s;
}

.skills-container .carousel-item i {
    font-size: 4rem;
    margin-bottom: 10px;
}


.skills-container .carousel-item:hover {
    color: #000;
}

/* Section Experiência — minimalista */
.experience-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    padding: 60px 20px;
    color: var(--text2-color);
}

.experience-content {
    width: 100%;
}

.experience-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
    margin-bottom: 24px;
}

.experience-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.company-mark {
    display: block;
    width: 44px;
    height: 44px;
    border-radius: 12px;
    object-fit: cover;
    flex-shrink: 0;
}

.experience-brand h2 {
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--text2-color);
}

.experience-role {
    display: block;
    color: var(--text3-color);
    font-size: 0.9rem;
}

.experience-meta {
    color: var(--text3-color);
    font-size: 0.9rem;
}

.experience-summary {
    max-width: 700px;
    text-align: left;
    color: var(--text3-color);
    margin-bottom: 30px;
}

.experience-projects {
    margin-bottom: 30px;
}

.experience-projects .faq-question p,
.experience-projects .faq-answer {
    text-align: left;
}

.experience-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.experience-tags span {
    display: inline-block;
    background: transparent;
    border: 1px solid #ddd;
    color: var(--text3-color);
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 500;
    transition: .25s;
}

.experience-tags span:hover {
    background: var(--text2-color);
    border-color: var(--text2-color);
    color: var(--text1-color);
}

/* Section projetos */
.projects-container {
    background: var(--gradient);
    display: flex;
    justify-content: center;
    flex-direction: column;
    align-items: center;
    padding: 40px;
    width: 100%;
}

.projects-container .section-title {
    color: var(--text1-color);
}

.projects-container .project-content {
    position: relative;
    display: flex;
    align-items: center;
    gap: 48px;
    margin-bottom: 40px;
    padding: 40px 40px 36px;
    background: #ffffff;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(6, 14, 4, 0.12);
    transition: transform 0.35s ease, box-shadow 0.35s ease;
}

.projects-container .project-content::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 5px;
    background: var(--gradient);
}

.projects-container .project-content:hover {
    transform: translateY(-6px);
    box-shadow: 0 24px 48px rgba(6, 14, 4, 0.2);
}

.projects-container .project-content:last-child {
    margin-bottom: 0;
}

.projects-container .project-image {
    position: relative;
    width: 100%;
    aspect-ratio: 16 / 10;
    overflow: hidden;
    border-radius: 18px;
    background: #eceee7;
}

.projects-container .project-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: 0.4s;
}

.projects-container .project-image:hover img {
    filter: brightness(0.6);
}

.projects-container .project-image .overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 20px;
    opacity: 0;
    transition: 0.3s;
}

.projects-container .project-image:hover .overlay {
    opacity: 1;
}

.projects-container .project-image .icon-link {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.15);
    border: 1px solid rgba(255, 255, 255, 0.4);
    backdrop-filter: blur(6px);
    color: var(--text1-color);
    font-size: 1.4rem;
    transition: 0.3s;
}

.projects-container .project-image .icon-link:hover {
    background: var(--text1-color);
    color: var(--main-color);
    transform: translateY(-4px);
}

.projects-container .project-description {
    display: flex;
    flex-direction: column;
    max-width: 50%;
    gap: 10px;
}

.projects-container .project-description h2,
.projects-container .project-description p {
    color: var(--text2-color);
}

.projects-container .project-description h2 {
    font-size: 1.7rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.projects-container .project-description p {
    font-size: 1rem;
    color: var(--text3-color);
    max-width: 60ch;
}

.projects-container .project-tags span {
    display: inline-block;
    background: #eef1e8;
    border: 1px solid transparent;
    color: var(--tertiary-color);
    padding: 5px 12px;
    margin: 4px 8px 4px 0;
    border-radius: 20px;
    font-size: 14px;
    font-weight: 500;
    transition: .3s;
}

.projects-container .project-tags span:hover {
    background: var(--main-color);
    color: var(--text1-color);
    transform: scale(1.08);
}

.projects-container .btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    width: fit-content;
    padding: 12px 24px;
    background: var(--text2-color);
    color: var(--text1-color);
    text-decoration: none;
    border-radius: 30px;
    font-size: 16px;
    font-weight: 600;
    margin-top: 10px;
    transition: 0.3s;
}

.projects-container .btn:hover {
    background: var(--main-color);
    color: var(--text1-color);
    transform: scale(1.05);
}

/* Section Contato */
.contact-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    color: var(--text2-color);
    position: relative;
    background-size: cover;
}

.contact-container {
    display: grid;
    padding: 40px;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 2rem;
    width: 50%;
    max-width: 1200px;
    margin: 0 auto;
    align-items: start;
    background-size: cover;
}

.contact-container h2 {
    font-size: 1.5rem;
    color: var(--text3-color);
    text-align: center;
    margin-bottom: 1rem;
}

/* Formulário */
.form-section {
    display: flex;
    flex-direction: column;
    justify-content: center;
    grid-column: 1;
    grid-row: span 2; /* Indica q está ocupando duas linhas */
    width: 100%;
    height: 100%;
    border-radius: 20px;
    background-color: var(--text1-color);
    padding: 2rem;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.form-section input, .form-section textarea {
    width: 100%;
    padding: 0.8rem;
    margin-bottom: 1rem;
    border: 1px solid #ddd;
    border-radius: 10px;
    font-size: 1rem;
}

.form-section button {
    width: 100%;
    padding: 0.8rem;
    background-color: var(--secondary-color);
    color: #fff;
    border: none;
    border-radius: 10px;
    font-size: 1rem;
    cursor: pointer;
    transition: background-color 0.3s ease;
}

.navigation, .social-icons {
    background-color: var(--text1-color);
    width: 100%;
    border-radius: 20px;
    padding: 2rem;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.form-section button:hover {
    background-color: var(--main-color);
}

/* Navegação */
.navigation {
    grid-column: 2;
    grid-row: 1;
    text-align: center;
}

.navigation h2 {
    font-size: 1.5rem;
    color: var(--text3-color);
    margin-bottom: 1rem;
}

.navigation ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.navigation ul li {
    margin: 0.5rem 0;
}

.navigation ul li a {
    text-decoration: none;
    color: var(--text3-color);
    font-size: 1rem;
    transition: color 0.3s ease;
}

.navigation ul li a:hover {
    color: var(--secondary-color);
}

/* Redes Sociais */
.social-icons {
    display: flex;
    flex-direction: column;
    grid-column: 2;
    grid-row: 2;
    text-align: center;
}

.social-icons-elements {
    display: flex;
    justify-content: center;
    gap: 1rem;
}

.social-icons-section h2 {
    font-size: 1.5rem;
    color: var(--text3-color);
    margin-bottom: 1rem;
}

.social-icons a {
    width: 50px;
    height: 50px;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--secondary-color);
    color: white;
    border-radius: 50%;
    font-size: 1.5rem;
    text-decoration: none;
    transition: background-color 0.3s ease;
}

.social-icons a:hover {
    background-color: var(--main-color);
}

/* Ajustando a posição do redirecionamento */
#hello {
    scroll-margin-top: 80px;
}

#about {
    scroll-margin-top: 100px; 
}

#tech {
    scroll-margin-top: 220px; 
}

#projects {
    scroll-margin-top: 90px; 
}

#contact-id {
    scroll-margin-top: 90px; 
}

/* Section Perguntas Frequentes */
.faq-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    color: var(--text2-color);
    background-size: cover;
}

.faq-section .text-center {
    padding: 40px;
}

.faq-section .faq-question p {
    font-size: 1.05rem;
    color: var(--text2-color);
    margin: 0;
    text-align: left;
}


.faq-item {
    margin-bottom: 12px;
    background: #fafafa;
    border: 1px solid #eee;
    border-radius: 14px;
    overflow: hidden;
    transition: box-shadow 0.3s, transform 0.3s;
}

.faq-item:hover {
    box-shadow: 0 8px 24px rgba(2, 5, 10, 0.06);
    transform: translateY(-2px);
}

.faq-question {
    width: 100%;
    background: none;
    border: none;
    font-size: 1.05rem;
    font-weight: 600;
    text-align: left;
    padding: 20px 24px;
    color: var(--text2-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
}

.faq-question:hover {
    background-color: #f4f6f1;
}

.faq-toggle {
    background-color: var(--main-color);
    color: white;
    border-radius: 50%;
    min-width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s, background-color 0.3s;
}

.faq-question:hover .faq-toggle {
    background-color: var(--secondary-color);
    transform: rotate(180deg);
}

.faq-answer {
    max-height: 0;
    overflow: hidden;
    font-size: 1rem;
    color: var(--text3-color);
    padding: 0 24px;
    transition: all 0.5s ease-in-out;
}

.faq-answer.active {
    max-height: 600px;
    padding: 10px 24px 20px;
}

.fa-chevron-down, .fa-chevron-up {
    font-size: 1rem;
}

/* Quadradinho lateral */
.back-to-top {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background-color: var(--secondary-color);
    color: white;
    width: 50px;
    height: 50px;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 1.5rem;
    cursor: pointer;
    border: none;
    border-radius: 50%;
    transition: background-color 0.3s ease;
}

.back-to-top:hover {
    background-color: var(--main-color);
}

/* Responsividade */
/* Telas até 1280px - celulares/alguns tablets */
@media (max-width: 1280px) {
    section .text-center {
        width: 100%;
    }

    .hello-container .text-center {
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .hello-container #hello-text {
        font-size: 1.5rem;
    }

    .hello-container #name-text {
        display: flex;
        justify-content: center;
        width: 300px;
    }

    .presentation-container img {
        height: 200px;
        width: 200px;
        margin-right: 0;
    }

    .presentation-container .text-center {
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .presentation-container #curriculobutton {
        margin-top: 20px;
    }

    .projects-container .project-content {
        flex-direction: column;
        text-align: center;
        padding: 20px;
    }

    .projects-container .project-description {
        max-width: 80%;
    }

    .projects-container .btn {
        width: 100%;
    }

    .contact-container {
        display: flex;
        flex-direction: column;
        width: 80%;
        padding: 20px;
    }

    .experience-header {
        flex-direction: column;
        align-items: flex-start;
    }
}

/* Ajusta espaçamento abaixo do header flutuante em telas menores */
@media (max-width: 1280px) {
    .wave {
        margin-top: 60px;
    }
}

/* Altera o header em 1040px */
@media (max-width: 1040px) {
    .nav-bar {
        display: none;
    }
}

/* Telas até 768px - celulares entre 768 e 1650 */
@media (min-width: 768px) and (max-width: 1650px) {
    .presentation-container #curriculobutton {
        margin-top: 20px;
    }

    .presentation-container img {
        height: 350px;
    }
}

/* Acima de 768px entre 1300px mantém a seção presentation no formato padrão */
@media (min-width: 768px) and (max-width: 1300px) {
    .presentation-container .text-center {
        flex-direction: row;
        align-items: flex-start;
        text-align: left;
    }

    .presentation-container img {
        height: 300px;
        width: 300px;
        margin-right: 40px;
    }
}

@import url('https://fonts.googleapis.com/css2?family=Inter+Tight:ital,wght@0,100..900;1,100..900&family=Open+Sans:ital,wght@0,300..800;1,300..800&display=swap');


/* Animação */
@keyframes colorChange {
    0% {
        color: var(--tertiary-color);
    }
    25% {
        color: var(--main-color);
    }
    50% {
        color: var(--secondary-color);
    }
    75% {
        color: var(--inverse-color);
    }
    100% {
        color: var(--tertiary-color);
    }
}

/* Animação para rolagem contínua */
@keyframes scroll {
    0% {
        transform: translateX(0);
    }
    100% {
        transform: translateX(-100%);
    }
}

/* Animação de flutuar */
@keyframes float {
    0% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
    100% {
        transform: translateY(0);
    }
}

/* Mudar bordas de imagem */
@keyframes borderRadiusChange {
    0% {
        border-radius: 42.5% 34% 25.5% 51% / 42.5% 25.5% 51% 34%;
    }
    50% {
        border-radius: 25.5% 42.5% 51% 34% / 34% 42.5% 25.5% 42.5%;
    }
    100% {
        border-radius: 42.5% 34% 25.5% 51% / 42.5% 25.5% 51% 34%;
    }
}

:root {
    --main-color: #374B32;
    --secondary-color: #4CA035;
    --tertiary-color: #3d5e35;
    --inverse-color: orange;
    --text1-color: white;
    --text2-color: #171717;
    --text3-color: #555;
    --background: white;
    /* --background: #2C332B; */
    --header: white;
    --gradient: linear-gradient(90deg, #47753B 0%, #8BC34A 100%);
    --blur: blur(5px);
}

/* Configurações globais */
* {
    font-family: 'Inter Tight', sans-serif;
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

a {
    text-decoration: none;
    color: inherit;
}

html {
    scroll-behavior: smooth;
}

html, body {
    overflow-x: hidden !important; 
}

/* Scroll */
body::-webkit-scrollbar {
    width: 12px;
    background: #ffffff00;
}

body::-webkit-scrollbar-thumb {
    border-radius: 5px;
    transition: all 0.3s ease;
    background-color: var(--text3-color);
}

body::-webkit-scrollbar-thumb:hover {
    background: rgba(88, 88, 88, 0.459);
}

body {
    display: flex;
    background-color: var(--background);
    font-size: 16px;
    line-height: 1.5;
    width: 100%;
    height: 100%;
}

/* Header */
header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    background-color: rgba(255, 255, 255, 0.119);
    backdrop-filter: var(--blur);
    -webkit-backdrop-filter: var(--blur);
    width: max-content;
    max-width: 94vw;
    padding: 10px 24px;
    margin: 20px auto;
    border-radius: 20px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
    position: fixed;
    top: 0;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1000;
}

header .logo {
    display: flex;
    align-items: center;
}

header .logo img {
    border-radius: 50%;
    height: 50px;
    width: 50px;
    object-fit: cover; 
    transition: transform 0.5s, color 0.5s;
}

header .logo img:hover {
    transform: rotate(360deg);
}

header nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

header nav ul {
    display: flex;
    list-style: none;
    white-space: nowrap;
}

header nav ul li {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 8px;
    font-size: 0.95rem;
    font-weight: 500;
    transition: transform 0.3s, color 0.3s;
}

header .fa-brands {
    font-size: 1.8rem;
    margin-right: 10px;
    transition: transform 0.5s, color 0.5s;
}

header .fa-brands:hover, nav ul li:hover {
    transform: scale(1.1);
    color: var(--main-color);
}

/* Estilo para todas alinhar todas as sections */
section .text-center {
    display: flex;
    width: 50%;
    flex-direction: column;
}

/* Padrão de títulos de seção */
.section-label {
    display: block;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 4px;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--secondary-color);
    margin-bottom: 8px;
}

.section-label-light {
    color: rgba(255, 255, 255, 0.75);
}

.section-title {
    text-align: center;
    font-size: clamp(1.6rem, 4vw, 2.2rem);
    font-weight: 700;
    letter-spacing: -0.5px;
    color: var(--text2-color);
    margin-bottom: 40px;
}

/* "Onda" da tela principal */
.wave {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
}

/* Section principal */
main {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    margin-top: 100px;
}

.hello-container {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: 90vh;
    color: var(--text2-color);
}

.hello-container .text-center {
    width: 100%;
    align-items: center;
    text-align: center;
}

.hello-container #hello-text {
    background-color: var(--tertiary-color);
    font-weight: 300;
    color: var(--text1-color);
    padding: 7px 16px;
    border-radius: 10px;
    margin-right: 10px;
    white-space: nowrap;
}

.hello-container span {
    font-size: 2rem;
    font-weight: 400;
}

.hello-container #greeting-text {
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
}

.hello-container #name-text {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    margin-top: 10px;
    transition: margin-top 0.3s;
    animation: float 5s infinite;
}

.hello-container h1#name {
    text-align: center;
    color: var(--text2-color);
    font-size: clamp(3rem, 8vw, 5.5rem);
    font-weight: 800;
    letter-spacing: -2px;
    transition: 0.7s;
    line-height: 1;
    margin-top: 5px;
    cursor: pointer;
    animation: colorChange 10s infinite;
}

.hello-container h1#name:hover {
    transform: scale(1.1);
}

.hello-container #job-text {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin-bottom: 20px;
}

.hello-container #job-text p {
    font-size: 1.5rem;
    font-weight: 300;
    color: var(--text3-color);
    transition: font-size 0.3s;
}

.hello-container #job-text span {
    font-weight: 300;
    font-size: 16px;
    color: var(--text3-color);
}

.hello-container button {
    background-color: var(--tertiary-color);
    color: var(--text1-color);
    padding: 15px;
    border: none;
    border-radius: 30px;
    font-size: 1rem;
    cursor: pointer;
    width: 200px;
    transition: transform 0.5s;
}

.hello-container button:hover {
    background-color: var(--main-color);
    transform: scale(1.04);
}

.hello-container button i,
.projects-container .btn i {
    transition: transform 0.3s;
}

.hello-container button:hover i,
.projects-container .btn:hover i {
    transform: translateX(5px);
}

.hello-container .hello-banner {  /* Mantém o titulo principal (eduardo fabri) alinhado */
    width: 50%;
    margin: 140px auto;
}

/* Section de apresentação */
.presentation-container {
    display: flex;
    width: 100%;
    background: var(--gradient);
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 40px;
    color: var(--text1-color);
}

.presentation-container .text-center {
    display: flex;
    flex-direction: row;
}

.presentation-container img {
    animation: borderRadiusChange 10s infinite;
    height: 320px;
    width: 300px;
    margin-right: 40px;
    border-radius: 50px;
    object-fit: cover;
    transition: 0.3s;
    cursor: pointer;
    box-shadow: 10px 10px 5px rgba(2, 5, 10, 0.1);
}

.presentation-container img:hover {
    transform: scale(1.04);
}

.presentation-container .text-me {
    display: flex;
    margin-top: 20px;
    flex-direction: column;
}

.presentation-container .text-me #about-me {
    font-size: 2rem;
    font-weight: 700;
    transition: font-size 0.3s;
}

.presentation-container .text-me #about-me:hover {
    font-size: 2.5rem;
}

.presentation-container #curriculobutton {
    background-color: var(--text2-color);
    color: #fff;
    padding: 10px;
    border: none;
    border-radius: 30px;
    font-size: 1.3rem;
    cursor: pointer;
    width: 200px;
    margin-top: 90px;
    transition: background-color 0.5s;
    border: 1px solid transparent;
    transition: transform 0.5s;
}

.presentation-container #curriculobutton:hover {
    background-color: var(--main-color);
    transform: scale(1.04);
}

/* Section Skills */
.skills-container {
    text-align: center;
    font-family: Arial, sans-serif;
    margin: 50px;
}

.skills-container .skills-title {
    margin-bottom: 50px;
}

.skills-container .carousel {
    position: relative;
    overflow: hidden;
    width: 100%;
    max-width: 800px;
    margin: 0 auto;

    /* Máscara para criar efeito de opacidade nas bordas */
    mask-image: linear-gradient(to right, transparent, black 15%, black 85%, transparent);
    -webkit-mask-image: linear-gradient(to right, transparent, black 15%, black 85%, transparent);
}

.skills-container .carousel-track {
    display: flex;
    animation: scroll 11s linear infinite; 
}

.skills-container .carousel-item {
    min-width: 200px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    color: #aaa;
    transition: color 0.3s;
}

.skills-container .carousel-item i {
    font-size: 4rem;
    margin-bottom: 10px;
}


.skills-container .carousel-item:hover {
    color: #000;
}

/* Section Experiência — minimalista */
.experience-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    padding: 60px 20px;
    color: var(--text2-color);
}

.experience-content {
    width: 100%;
}

.experience-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
    margin-bottom: 24px;
}

.experience-brand {
    display: flex;
    align-items: center;
    gap: 14px;
}

.company-mark {
    display: block;
    width: 44px;
    height: 44px;
    border-radius: 12px;
    object-fit: cover;
    flex-shrink: 0;
}

.experience-brand h2 {
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--text2-color);
}

.experience-role {
    display: block;
    color: var(--text3-color);
    font-size: 0.9rem;
}

.experience-meta {
    color: var(--text3-color);
    font-size: 0.9rem;
}

.experience-summary {
    max-width: 700px;
    text-align: left;
    color: var(--text3-color);
    margin-bottom: 30px;
}

.experience-projects {
    margin-bottom: 30px;
}

.experience-projects .faq-question p,
.experience-projects .faq-answer {
    text-align: left;
}

.experience-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.experience-tags span {
    display: inline-block;
    background: transparent;
    border: 1px solid #ddd;
    color: var(--text3-color);
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 13px;
    font-weight: 500;
    transition: .25s;
}

.experience-tags span:hover {
    background: var(--text2-color);
    border-color: var(--text2-color);
    color: var(--text1-color);
}

/* Section projetos */
.projects-container {
    background: var(--gradient);
    display: flex;
    justify-content: center;
    flex-direction: column;
    align-items: center;
    padding: 40px;
    width: 100%;
}

.projects-container .section-title {
    color: var(--text1-color);
}

.projects-container .project-content {
    position: relative;
    display: flex;
    align-items: center;
    gap: 36px;
    margin-bottom: 36px;
    padding: 28px;
    background: linear-gradient(180deg, #ffffff 0%, #fbfdf8 100%);
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 8px 24px rgba(22, 30, 18, 0.08);
    transition: transform 0.35s cubic-bezier(.2,.9,.3,1), box-shadow 0.35s;
    border: 1px solid rgba(60,80,46,0.06);
}

.projects-container .project-content::before {
    /* slim accent on the left to connect with the green brand */
    content: "";
    position: absolute;
    top: 12px;
    left: 12px;
    width: 6px;
    bottom: 12px;
    border-radius: 6px;
    background: var(--gradient);
    opacity: 0.95;
}

.projects-container .project-content:hover {
    transform: translateY(-8px) scale(1.005);
    box-shadow: 0 28px 60px rgba(18, 28, 12, 0.16);
}

.projects-container .project-content:last-child {
    margin-bottom: 0;
}


.projects-container .project-image {
    position: relative;
    width: 40%;
    min-width: 220px;
    aspect-ratio: 4 / 3;
    overflow: hidden;
    border-radius: 12px;
    background: linear-gradient(180deg, #f6f8f2, #eef3e6);
    flex-shrink: 0;
}

.projects-container .project-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.6s ease, filter 0.35s ease;
    display: block;
}

.projects-container .project-image:hover img {
    transform: scale(1.06) rotate(-0.6deg);
    filter: brightness(0.72) saturate(1.02);
}


.projects-container .project-image .overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 16px;
    opacity: 0;
    transition: opacity 0.28s ease, background 0.28s ease;
    background: linear-gradient(180deg, rgba(55,75,50,0.0), rgba(55,75,50,0.22));
}

.projects-container .project-image:hover .overlay {
    opacity: 1;
}

.projects-container .project-image .icon-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(6px);
    color: var(--text1-color);
    font-size: 1.25rem;
    transition: transform 0.25s ease, background 0.25s ease, color 0.25s ease;
    box-shadow: 0 4px 14px rgba(8, 12, 6, 0.06);
}

.projects-container .project-image .icon-link:hover {
    background: var(--text1-color);
    color: var(--main-color);
    transform: translateY(-6px) scale(1.02);
}

.projects-container .project-description {
    display: flex;
    flex-direction: column;
    max-width: 58%;
    gap: 10px;
    padding-right: 8px;
}

.projects-container .project-description h2,
.projects-container .project-description p {
    color: var(--text2-color);
}

.projects-container .project-description h2 {
    font-size: 1.7rem;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.projects-container .project-description p {
    font-size: 1rem;
    color: var(--text3-color);
    max-width: 60ch;
}

.projects-container .project-tags span {
    display: inline-block;
    background: rgba(76,160,53,0.08);
    border: 1px solid rgba(76,160,53,0.16);
    color: var(--main-color);
    padding: 6px 12px;
    margin: 6px 10px 6px 0;
    border-radius: 14px;
    font-size: 13px;
    font-weight: 600;
    transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease;
}

.projects-container .project-tags span:hover {
    background: var(--main-color);
    color: var(--text1-color);
    transform: translateY(-4px) scale(1.03);
}

.projects-container .btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    width: fit-content;
    padding: 10px 20px;
    background: var(--main-color);
    color: var(--text1-color);
    text-decoration: none;
    border-radius: 12px;
    font-size: 15px;
    font-weight: 700;
    margin-top: 12px;
    transition: transform 0.18s ease, box-shadow 0.18s ease, opacity 0.18s;
    box-shadow: 0 8px 24px rgba(60,80,46,0.12);
}

.projects-container .btn:hover {
    transform: translateY(-4px) scale(1.02);
    opacity: 0.98;
    box-shadow: 0 14px 40px rgba(60,80,46,0.14);
}

/* Section Contato */
.contact-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    color: var(--text2-color);
    position: relative;
    background-size: cover;
}

.contact-container {
    display: grid;
    padding: 40px;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 2rem;
    width: 50%;
    max-width: 1200px;
    margin: 0 auto;
    align-items: start;
    background-size: cover;
}

.contact-container h2 {
    font-size: 1.5rem;
    color: var(--text3-color);
    text-align: center;
    margin-bottom: 1rem;
}

/* Formulário */
.form-section {
    display: flex;
    flex-direction: column;
    justify-content: center;
    grid-column: 1;
    grid-row: span 2; /* Indica q está ocupando duas linhas */
    width: 100%;
    height: 100%;
    border-radius: 20px;
    background-color: var(--text1-color);
    padding: 2rem;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.form-section input, .form-section textarea {
    width: 100%;
    padding: 0.8rem;
    margin-bottom: 1rem;
    border: 1px solid #ddd;
    border-radius: 10px;
    font-size: 1rem;
}

.form-section button {
    width: 100%;
    padding: 0.8rem;
    background-color: var(--secondary-color);
    color: #fff;
    border: none;
    border-radius: 10px;
    font-size: 1rem;
    cursor: pointer;
    transition: background-color 0.3s ease;
}

.navigation, .social-icons {
    background-color: var(--text1-color);
    width: 100%;
    border-radius: 20px;
    padding: 2rem;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.form-section button:hover {
    background-color: var(--main-color);
}

/* Navegação */
.navigation {
    grid-column: 2;
    grid-row: 1;
    text-align: center;
}

.navigation h2 {
    font-size: 1.5rem;
    color: var(--text3-color);
    margin-bottom: 1rem;
}

.navigation ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.navigation ul li {
    margin: 0.5rem 0;
}

.navigation ul li a {
    text-decoration: none;
    color: var(--text3-color);
    font-size: 1rem;
    transition: color 0.3s ease;
}

.navigation ul li a:hover {
    color: var(--secondary-color);
}

/* Redes Sociais */
.social-icons {
    display: flex;
    flex-direction: column;
    grid-column: 2;
    grid-row: 2;
    text-align: center;
}

.social-icons-elements {
    display: flex;
    justify-content: center;
    gap: 1rem;
}

.social-icons-section h2 {
    font-size: 1.5rem;
    color: var(--text3-color);
    margin-bottom: 1rem;
}

.social-icons a {
    width: 50px;
    height: 50px;
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--secondary-color);
    color: white;
    border-radius: 50%;
    font-size: 1.5rem;
    text-decoration: none;
    transition: background-color 0.3s ease;
}

.social-icons a:hover {
    background-color: var(--main-color);
}

/* Ajustando a posição do redirecionamento */
#hello {
    scroll-margin-top: 80px;
}

#about {
    scroll-margin-top: 100px; 
}

#tech {
    scroll-margin-top: 220px; 
}

#projects {
    scroll-margin-top: 90px; 
}

#contact-id {
    scroll-margin-top: 90px; 
}

/* Section Perguntas Frequentes */
.faq-section {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    color: var(--text2-color);
    background-size: cover;
}

.faq-section .text-center {
    padding: 40px;
}

.faq-section .faq-question p {
    font-size: 1.05rem;
    color: var(--text2-color);
    margin: 0;
    text-align: left;
}


.faq-item {
    margin-bottom: 12px;
    background: #fafafa;
    border: 1px solid #eee;
    border-radius: 14px;
    overflow: hidden;
    transition: box-shadow 0.3s, transform 0.3s;
}

.faq-item:hover {
    box-shadow: 0 8px 24px rgba(2, 5, 10, 0.06);
    transform: translateY(-2px);
}

.faq-question {
    width: 100%;
    background: none;
    border: none;
    font-size: 1.05rem;
    font-weight: 600;
    text-align: left;
    padding: 20px 24px;
    color: var(--text2-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
}

.faq-question:hover {
    background-color: #f4f6f1;
}

.faq-toggle {
    background-color: var(--main-color);
    color: white;
    border-radius: 50%;
    min-width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: transform 0.3s, background-color 0.3s;
}

.faq-question:hover .faq-toggle {
    background-color: var(--secondary-color);
    transform: rotate(180deg);
}

.faq-answer {
    max-height: 0;
    overflow: hidden;
    font-size: 1rem;
    color: var(--text3-color);
    padding: 0 24px;
    transition: all 0.5s ease-in-out;
}

.faq-answer.active {
    max-height: 600px;
    padding: 10px 24px 20px;
}

.fa-chevron-down, .fa-chevron-up {
    font-size: 1rem;
}

/* Quadradinho lateral */
.back-to-top {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background-color: var(--secondary-color);
    color: white;
    width: 50px;
    height: 50px;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 1.5rem;
    cursor: pointer;
    border: none;
    border-radius: 50%;
    transition: background-color 0.3s ease;
}

.back-to-top:hover {
    background-color: var(--main-color);
}

/* Responsividade */
/* Telas até 1280px - celulares/alguns tablets */
@media (max-width: 1280px) {
    section .text-center {
        width: 100%;
    }

    .hello-container .text-center {
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .hello-container #hello-text {
        font-size: 1.5rem;
    }

    .hello-container #name-text {
        display: flex;
        justify-content: center;
        width: 300px;
    }

    .presentation-container img {
        height: 200px;
        width: 200px;
        margin-right: 0;
    }

    .presentation-container .text-center {
        flex-direction: column;
        align-items: center;
        text-align: center;
    }

    .presentation-container #curriculobutton {
        margin-top: 20px;
    }

    .projects-container .project-content {
        flex-direction: column;
        text-align: center;
        padding: 20px;
    }

    .projects-container .project-description {
        max-width: 80%;
    }

    .projects-container .btn {
        width: 100%;
    }

    .contact-container {
        display: flex;
        flex-direction: column;
        width: 80%;
        padding: 20px;
    }

    .experience-header {
        flex-direction: column;
        align-items: flex-start;
    }
}

/* Ajusta espaçamento abaixo do header flutuante em telas menores */
@media (max-width: 1280px) {
    .wave {
        margin-top: 60px;
    }
}

/* Altera o header em 1040px */
@media (max-width: 1040px) {
    .nav-bar {
        display: none;
    }
}

/* Telas até 768px - celulares entre 768 e 1650 */
@media (min-width: 768px) and (max-width: 1650px) {
    .presentation-container #curriculobutton {
        margin-top: 20px;
    }

    .presentation-container img {
        height: 350px;
    }
}

/* Acima de 768px entre 1300px mantém a seção presentation no formato padrão */
@media (min-width: 768px) and (max-width: 1300px) {
    .presentation-container .text-center {
        flex-direction: row;
        align-items: flex-start;
        text-align: left;
    }

    .presentation-container img {
        height: 300px;
        width: 300px;
        margin-right: 40px;
    }
}
